lines = [line.strip() for line in raw_data.strip().split("\n") if line.strip()]
header = lines[0].split("\t")
months = [m.strip().upper() for m in header[1:]]

official_db = {}
for line in lines[1:]:
    parts = line.split("\t")
    sym = parts[0].strip().upper()
    monthly = {}
    for idx, m in enumerate(months):
        val_str = parts[idx + 1].strip() if (idx + 1) < len(parts) else "-"
        if val_str in ("-", "", "None", "null"):
            monthly[m] = "-"
        else:
            try:
                monthly[m] = round(float(val_str), 4)
            except Exception:
                monthly[m] = "-"
    official_db[sym] = monthly

cache_dir = Path("cache")
cache_dir.mkdir(parents=True, exist_ok=True)
out_file = cache_dir / "futures_rollover_official.json"

payload = {
    "months": months,
    "symbols": sorted(list(official_db.keys())),
    "records": official_db
}

out_file.write_text(json.dumps(payload, indent=2), encoding="utf-8")
print(f"Successfully saved {len(official_db)} official symbols across {len(months)} months to {out_file}!")
